package com.abcvpn.service;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import java.time.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.abcvpn.entity.Subscription;import com.abcvpn.enumeration.SyncStatus;import com.abcvpn.repository.SubscriptionRepository;
class VpnSyncServiceTest {
 @Test void failureSchedulesRetry(){SubscriptionRepository repository=mock(SubscriptionRepository.class);VpnAccessService access=mock(VpnAccessService.class);Instant now=Instant.parse("2026-01-01T00:00:00Z");Subscription s=new Subscription(1,2,now.plusSeconds(100),false,"id","url",SyncStatus.PENDING,0,null,null,now,now);doThrow(new RuntimeException("down")).when(access).sync(s);new VpnSyncService(repository,access,Clock.fixed(now,ZoneOffset.UTC)).syncOne(s);verify(repository).markError(1,1,now.plusSeconds(10),"down");}
 @Test void expiredAccessGetsDisabled(){SubscriptionRepository repository=mock(SubscriptionRepository.class);VpnAccessService access=mock(VpnAccessService.class);Instant now=Instant.parse("2026-01-01T00:00:00Z");Subscription s=new Subscription(1,2,now.minusSeconds(1),false,"id","url",SyncStatus.SYNCED,0,null,null,now,now);when(repository.findExpiredNotQueued(now,500)).thenReturn(java.util.List.of(s));new VpnSyncService(repository,access,Clock.fixed(now,ZoneOffset.UTC)).queueExpired();verify(repository).markPending(1);}
}
